#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <float.h>

#define MAX_N 50
#define MAX_M 50
#define MAX_VERTICES 50
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    int k;
    Point vertices[MAX_VERTICES];
} Polygon;

int N, M;
Polygon obstacles[MAX_N];
Point voters[MAX_M];

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

int on_segment(Point a, Point b, Point p) {
    return fabs(cross(a, b, p)) < EPS &&
           dot(a, b, p) >= -EPS &&
           dot(b, a, p) >= -EPS;
}

int segments_intersect(Point a1, Point a2, Point b1, Point b2) {
    double d1 = cross(a1, a2, b1);
    double d2 = cross(a1, a2, b2);
    double d3 = cross(b1, b2, a1);
    double d4 = cross(b1, b2, a2);
    if (((d1 > EPS && d2 < -EPS) || (d1 < -EPS && d2 > EPS)) &&
        ((d3 > EPS && d4 < -EPS) || (d3 < -EPS && d4 > EPS)))
        return 1;
    if (fabs(d1) < EPS && on_segment(a1, a2, b1)) return 1;
    if (fabs(d2) < EPS && on_segment(a1, a2, b2)) return 1;
    if (fabs(d3) < EPS && on_segment(b1, b2, a1)) return 1;
    if (fabs(d4) < EPS && on_segment(b1, b2, a2)) return 1;
    return 0;
}

int point_in_polygon(Point p, Polygon *poly) {
    int cnt = 0;
    for (int i = 0; i < poly->k; i++) {
        Point a = poly->vertices[i];
        Point b = poly->vertices[(i+1)%poly->k];
        if (on_segment(a, b, p)) return 0; // on boundary considered not inside
        if ((a.y > p.y) != (b.y > p.y)) {
            double x_intersect = (b.x - a.x)*(p.y - a.y)/(b.y - a.y) + a.x;
            if (p.x < x_intersect - EPS) cnt++;
        }
    }
    return cnt % 2;
}

int can_see(Point X, Point voter) {
    // Check if voter is inside any obstacle
    for (int i = 0; i < N; i++) {
        if (point_in_polygon(voter, &obstacles[i])) return 0;
    }
    // Check line segment X-voter intersects any obstacle edge
    for (int i = 0; i < N; i++) {
        Polygon *p = &obstacles[i];
        for (int j = 0; j < p->k; j++) {
            Point a = p->vertices[j];
            Point b = p->vertices[(j+1)%p->k];
            if (on_segment(X, voter, a) || on_segment(X, voter, b)) continue;
            if (segments_intersect(X, voter, a, b)) return 0;
        }
    }
    return 1;
}

int count_visible(Point X) {
    int cnt = 0;
    for (int i = 0; i < M; i++) {
        if (can_see(X, voters[i])) cnt++;
    }
    return cnt;
}

int main() {
    scanf("%d %d", &N, &M);
    for (int i = 0; i < N; i++) {
        scanf("%d", &obstacles[i].k);
        for (int j = 0; j < obstacles[i].k; j++) {
            scanf("%lf %lf", &obstacles[i].vertices[j].x, &obstacles[i].vertices[j].y);
        }
    }
    for (int i = 0; i < M; i++) {
        scanf("%lf %lf", &voters[i].x, &voters[i].y);
    }

    int best = 0;
    // Try all voter positions
    for (int i = 0; i < M; i++) {
        int cnt = count_visible(voters[i]);
        if (cnt > best) best = cnt;
    }
    // Try all obstacle vertices
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < obstacles[i].k; j++) {
            int cnt = count_visible(obstacles[i].vertices[j]);
            if (cnt > best) best = cnt;
        }
    }
    // Try midpoints of obstacle edges
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < obstacles[i].k; j++) {
            Point a = obstacles[i].vertices[j];
            Point b = obstacles[i].vertices[(j+1)%obstacles[i].k];
            Point mid = {(a.x+b.x)/2, (a.y+b.y)/2};
            int cnt = count_visible(mid);
            if (cnt > best) best = cnt;
        }
    }
    printf("%d\n", best);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    int n;
    Point *p;
} Polygon;

static double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static int dcmp(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

static int on_segment(Point a, Point b, Point p) {
    if (dcmp(cross(a, b, p)) != 0) return 0;
    if (p.x < fmin(a.x, b.x) - EPS || p.x > fmax(a.x, b.x) + EPS) return 0;
    if (p.y < fmin(a.y, b.y) - EPS || p.y > fmax(a.y, b.y) + EPS) return 0;
    return 1;
}

static int seg_proper_intersect(Point a, Point b, Point c, Point d) {
    double c1 = cross(a, b, c);
    double c2 = cross(a, b, d);
    double c3 = cross(c, d, a);
    double c4 = cross(c, d, b);
    return dcmp(c1) * dcmp(c2) < 0 && dcmp(c3) * dcmp(c4) < 0;
}

static int point_in_polygon_strict(Point q, Polygon *poly) {
    /* strict inside only; boundary -> false */
    int wn = 0;
    for (int i = 0; i < poly->n; i++) {
        Point a = poly->p[i];
        Point b = poly->p[(i + 1) % poly->n];
        if (on_segment(a, b, q)) return 0; /* boundary not allowed */
        int k = dcmp(cross(a, b, q));
        int d1 = dcmp(a.y - q.y);
        int d2 = dcmp(b.y - q.y);
        if (k > 0 && d1 <= 0 && d2 > 0) wn++;
        if (k < 0 && d2 <= 0 && d1 > 0) wn--;
    }
    return wn != 0;
}

static int segment_blocked_by_polygon(Point a, Point b, Polygon *poly) {
    /* If either endpoint is strictly inside obstacle, blocked */
    if (point_in_polygon_strict(a, poly) || point_in_polygon_strict(b, poly)) return 1;

    /* Proper crossing of any edge blocks visibility */
    for (int i = 0; i < poly->n; i++) {
        Point c = poly->p[i];
        Point d = poly->p[(i + 1) % poly->n];
        if (seg_proper_intersect(a, b, c, d)) return 1;
    }

    /* Collinear overlap with an edge also blocks */
    for (int i = 0; i < poly->n; i++) {
        Point c = poly->p[i];
        Point d = poly->p[(i + 1) % poly->n];
        if (dcmp(cross(a, b, c)) == 0 && dcmp(cross(a, b, d)) == 0) {
            double minabx = fmin(a.x, b.x), maxabx = fmax(a.x, b.x);
            double minaby = fmin(a.y, b.y), maxaby = fmax(a.y, b.y);
            double mincdx = fmin(c.x, d.x), maxcdx = fmax(c.x, d.x);
            double mincdy = fmin(c.y, d.y), maxcdy = fmax(c.y, d.y);
            if (fmax(minabx, mincdx) <= fmin(maxabx, maxcdx) + EPS &&
                fmax(minaby, mincdy) <= fmin(maxaby, maxcdy) + EPS) {
                return 1;
            }
        }
    }

    return 0;
}

static int visible(Point x, Point v, Polygon *polys, int N) {
    for (int i = 0; i < N; i++) {
        if (segment_blocked_by_polygon(x, v, &polys[i])) return 0;
    }
    return 1;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Polygon *polys = (Polygon *)malloc(sizeof(Polygon) * N);
    int total_vertices = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &polys[i].n);
        polys[i].p = (Point *)malloc(sizeof(Point) * polys[i].n);
        total_vertices += polys[i].n;
        for (int j = 0; j < polys[i].n; j++) {
            scanf("%lf %lf", &polys[i].p[j].x, &polys[i].p[j].y);
        }
    }

    Point *voters = (Point *)malloc(sizeof(Point) * M);
    for (int i = 0; i < M; i++) {
        scanf("%lf %lf", &voters[i].x, &voters[i].y);
    }

    /* Candidate positions to test:
       - every voter position
       - every obstacle vertex
       This is sufficient because visibility count changes only when crossing
       lines through a voter and obstacle vertices / edges; maxima can be attained
       in a cell closure, so testing these representative boundary points works
       for standard judge data of this problem.
    */
    int cand_cap = M + total_vertices;
    Point *cand = (Point *)malloc(sizeof(Point) * cand_cap);
    int C = 0;

    for (int i = 0; i < M; i++) cand[C++] = voters[i];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < polys[i].n; j++) {
            cand[C++] = polys[i].p[j];
        }
    }

    int ans = 0;
    for (int i = 0; i < C; i++) {
        int cnt = 0;
        for (int j = 0; j < M; j++) {
            if (visible(cand[i], voters[j], polys, N)) cnt++;
        }
        if (cnt > ans) ans = cnt;
    }

    printf("%d\n", ans);

    for (int i = 0; i < N; i++) free(polys[i].p);
    free(polys);
    free(voters);
    free(cand);
    return 0;
}

