using namespace std;
using ld = long double;
const ld EPS = 1e-9;

struct Point {
    ld x, y;
    Point() : x(0), y(0) {}
    Point(ld x_, ld y_) : x(x_), y(y_) {}
    bool operator==(const Point& o) const {
        return fabsl(x - o.x) < EPS && fabsl(y - o.y) < EPS;
    }
};

using Polygon = vector<Point>;

ld cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}
Point operator-(const Point& a, const Point& b) {
    return Point(a.x - b.x, a.y - b.y);
}
Point operator+(const Point& a, const Point& b) {
    return Point(a.x + b.x, a.y + b.y);
}
Point operator*(const Point& a, ld t) {
    return Point(a.x * t, a.y * t);
}

int sgn(ld x) {
    if (fabsl(x) < EPS) return 0;
    return x < 0 ? -1 : 1;
}

bool onSegment(const Point& p, const Point& a, const Point& b) {
    return sgn(cross(a - p, b - p)) == 0 && 
           sgn((a.x - p.x) * (b.x - p.x)) <= 0 &&
           sgn((a.y - p.y) * (b.y - p.y)) <= 0;
}

bool segSegIntersect(const Point& a1, const Point& a2, const Point& b1, const Point& b2) {
    if (onSegment(a1, b1, b2) || onSegment(a2, b1, b2) ||
        onSegment(b1, a1, a2) || onSegment(b2, a1, a2)) return true;
    return sgn(cross(a2 - a1, b1 - a1)) * sgn(cross(a2 - a1, b2 - a1)) < 0 &&
           sgn(cross(b2 - b1, a1 - b1)) * sgn(cross(b2 - b1, a2 - b1)) < 0;
}

bool pointInPolygon(const Point& p, const Polygon& poly) {
    bool inside = false;
    int n = poly.size();
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        if ((poly[i].y > p.y) != (poly[j].y > p.y)) {
            ld xinters = (poly[j].x - poly[i].x) * (p.y - poly[i].y) / (poly[j].y - poly[i].y) + poly[i].x;
            if (p.x < xinters) inside = !inside;
        }
    }
    return inside;
}

bool visible(const Point& cand, const Point& voter, const vector<Polygon>& obstacles) {
    for (const auto& poly : obstacles) {
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            if (segSegIntersect(cand, voter, poly[i], poly[j])) {
                // check if intersection is only at endpoints
                if (cand == poly[i] || cand == poly[j] || voter == poly[i] || voter == poly[j])
                    continue;
                return false;
            }
        }
    }
    return true;
}

