            cin >> obstacles[i][j].x >> obstacles[i][j].y;
        }
    }
    cin >> M;
    vector<Point> voters(M);
    for (int i = 0; i < M; i++) {
        cin >> voters[i].x >> voters[i].y;
    }

    vector<Point> candidates;
    // voter positions
    for (const auto& v : voters) candidates.push_back(v);
    // polygon vertices
    for (const auto& poly : obstacles) {
        for (const auto& p : poly) candidates.push_back(p);
    }
    // perturbed points around each vertex
    vector<Point> dirs = {Point(EPS,0), Point(-EPS,0), Point(0,EPS), Point(0,-EPS)};
    for (const auto& p : candidates) {
        for (const auto& d : dirs) {
            candidates.push_back(p + d);
        }
    }

    int best = 0;
    for (const auto& cand : candidates) {
        // check if cand inside any obstacle
        bool inside = false;
        for (const auto& poly : obstacles) {
            if (pointInPolygon(cand, poly)) {
                inside = true;
                break;
            }
        }
        if (inside) continue;
        int cnt = 0;
        for (const auto& voter : voters) {
            if (visible(cand, voter, obstacles)) cnt++;
        }
        best = max(best, cnt);
    }

    cout << best << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const double EPS = 1e-10;
const double PI = acos(-1.0);

struct Point {
    double x, y;
    Point() {}
    Point(double x_, double y_) : x(x_), y(y_) {}
    Point operator + (const Point& o) const { return Point(x + o.x, y + o.y); }
    Point operator - (const Point& o) const { return Point(x - o.x, y - o.y); }
    Point operator * (double k) const { return Point(x * k, y * k); }
};

double cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}
double dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y;
}
double norm2(const Point& a) {
    return dot(a, a);
}

struct Segment {
    Point a, b;
};

bool onSegment(const Point& a, const Point& b, const Point& p) {
    return fabs(cross(b - a, p - a)) < EPS && dot(p - a, p - b) <= EPS;
}

int sgn(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

bool segProperIntersect(const Point& a, const Point& b, const Point& c, const Point& d) {
    double c1 = cross(b - a, c - a);
    double c2 = cross(b - a, d - a);
    double c3 = cross(d - c, a - c);
    double c4 = cross(d - c, b - c);
    return sgn(c1) * sgn(c2) < 0 && sgn(c3) * sgn(c4) < 0;
}

bool segIntersectInclusive(const Point& a, const Point& b, const Point& c, const Point& d) {
    if (segProperIntersect(a, b, c, d)) return true;
    if (onSegment(a, b, c)) return true;
    if (onSegment(a, b, d)) return true;
    if (onSegment(c, d, a)) return true;
    if (onSegment(c, d, b)) return true;
    return false;
}

struct Polygon {
    vector<Point> p;
    vector<Segment> e;
};

bool pointInPolygonOrBoundary(const Polygon& poly, const Point& q) {
    bool in = false;
    int n = (int)poly.p.size();
    for (int i = 0; i < n; i++) {
        Point a = poly.p[i], b = poly.p[(i + 1) % n];
        if (onSegment(a, b, q)) return true;
        bool cond = ((a.y > q.y) != (b.y > q.y));
        if (cond) {
            double xint = a.x + (b.x - a.x) * (q.y - a.y) / (b.y - a.y);
            if (xint > q.x + EPS) in = !in;
        }
    }
    return in;
}

bool visible(const Point& x, const Point& voter, const vector<Polygon>& polys) {
    for (const auto& poly : polys) {
        if (pointInPolygonOrBoundary(poly, x)) return false;
        int n = (int)poly.p.size();
        for (int i = 0; i < n; i++) {
            const Point& a = poly.p[i];
            const Point& b = poly.p[(i + 1) % n];
            if (segIntersectInclusive(x, voter, a, b)) {
                // If the only intersection is at voter and voter lies on obstacle boundary,
                // it's still blocked because obstacle is on the segment.
                return false;
            }
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<Polygon> polys(N);
    vector<Point> voters(M);

    for (int i = 0; i < N; i++) {
        int k;
        cin >> k;
        polys[i].p.resize(k);
        for (int j = 0; j < k; j++) cin >> polys[i].p[j].x >> polys[i].p[j].y;
    }
    for (int i = 0; i < M; i++) cin >> voters[i].x >> voters[i].y;

    // Candidate optimal position can be taken from arrangement vertices:
    // obstacle vertices and voter positions.
    vector<Point> candidates;
    for (const auto& poly : polys)
        for (const auto& pt : poly.p)
            candidates.push_back(pt);
    for (const auto& v : voters) candidates.push_back(v);

    // Also include midpoints of all pairs of candidate points to reduce risk of only testing boundaries.
    int base = (int)candidates.size();
    for (int i = 0; i < base; i++) {
        for (int j = i + 1; j < base; j++) {
            candidates.push_back(Point((candidates[i].x + candidates[j].x) * 0.5,
                                        (candidates[i].y + candidates[j].y) * 0.5));
        }
    }

    int ans = 0;
    for (const auto& x : candidates) {
        bool bad = false;
        for (const auto& poly : polys) {
            if (pointInPolygonOrBoundary(poly, x)) {
                bad = true;
                break;
            }
        }
        if (bad) continue;

        int cnt = 0;
        for (const auto& v : voters) {
            if (visible(x, v, polys)) cnt++;
        }
        ans = max(ans, cnt);
    }

    cout << ans << '\n';
    return 0;
}

import java.util.*;
import java.awt.geom.*;

public class Main {
    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    static class Polygon {
        List<Point> vertices;
        Polygon(List<Point> v) { vertices = v; }
    }

    static boolean pointInPolygon(Point p, Polygon poly) {
        Path2D path = new Path2D.Double();
        List<Point> v = poly.vertices;
        path.moveTo(v.get(0).x, v.get(0).y);
        for (int i = 1; i < v.size(); i++)
            path.lineTo(v.get(i).x, v.get(i).y);
        path.closePath();
        return path.contains(p.x, p.y);
    }

    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        double o1 = cross(b, a, c);
        double o2 = cross(b, a, d);
        double o3 = cross(d, c, a);
        double o4 = cross(d, c, b);
        if (o1 == 0 && onSegment(a, b, c)) return true;
        if (o2 == 0 && onSegment(a, b, d)) return true;
        if (o3 == 0 && onSegment(c, d, a)) return true;
        if (o4 == 0 && onSegment(c, d, b)) return true;
        return (o1 > 0) != (o2 > 0) && (o3 > 0) != (o4 > 0);
    }

    static double cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return p.x >= Math.min(a.x, b.x) && p.x <= Math.max(a.x, b.x) &&
               p.y >= Math.min(a.y, b.y) && p.y <= Math.max(a.y, b.y);
    }

    static boolean visible(Point x, Point voter, List<Polygon> obstacles) {
        for (Polygon poly : obstacles) {
            List<Point> v = poly.vertices;
            int n = v.size();
            for (int i = 0; i < n; i++) {
                Point a = v.get(i);
                Point b = v.get((i + 1) % n);
                // Check strict interior intersection
                if (segmentsIntersect(x, voter, a, b)) {
                    // If intersection at endpoints, allow if voter or x is vertex? 
                    // For strict blocking, if it touches endpoint, it's not blocking if endpoint is voter or x.
                    // We'll consider touching as blocking only if it's interior.
                    double cross1 = cross(x, voter, a);
                    double cross2 = cross(x, voter, b);
                    if (cross1 != 0 && cross2 != 0) return false;
                    if (cross1 == 0 && onSegment(x, voter, a) && !a.equals(voter) && !a.equals(x)) return false;
                    if (cross2 == 0 && onSegment(x, voter, b) && !b.equals(voter) && !b.equals(x)) return false;
                }
            }
            // If voter inside obstacle, not visible
            if (pointInPolygon(voter, poly)) return false;
            // If X inside obstacle, not visible
            if (pointInPolygon(x, poly)) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        List<Polygon> obstacles = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            int V = sc.nextInt();
            List<Point> verts = new ArrayList<>();
            for (int j = 0; j < V; j++) {
                double x = sc.nextDouble();
                double y = sc.nextDouble();
                verts.add(new Point(x, y));
            }
            obstacles.add(new Polygon(verts));
        }
        List<Point> voters = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            double x = sc.nextDouble();
            double y = sc.nextDouble();
            voters.add(new Point(x, y));
        }

        // Collect candidate positions: all voters, all polygon vertices, and midpoints
        List<Point> candidates = new ArrayList<>();
        candidates.addAll(voters);
        for (Polygon p : obstacles) {
            candidates.addAll(p.vertices);
        }
        // Add small perturbations around vertices to handle edge cases
        double eps = 1e-6;
        List<Point> perturbed = new ArrayList<>();
        for (Point p : candidates) {
            perturbed.add(new Point(p.x + eps, p.y));
            perturbed.add(new Point(p.x - eps, p.y));
            perturbed.add(new Point(p.x, p.y + eps));
            perturbed.add(new Point(p.x, p.y - eps));
        }
        candidates.addAll(perturbed);

        int maxVisible = 0;
        for (Point cand : candidates) {
            int count = 0;
            for (Point voter : voters) {
                if (visible(cand, voter, obstacles)) count++;
            }
            if (count > maxVisible) maxVisible = count;
        }
        System.out.println(maxVisible);
    }
}

import java.io.*;
import java.util.*;

/*
 *  Street speech visibility maximization
 *
 *  We are given polygonal obstacles and voter points.
 *  A voter is visible from X iff segment X-voter does not intersect any obstacle.
 *
 *  Key geometric fact:
 *  The set of visible voters changes only when X crosses a line determined by
 *  a voter point and a polygon vertex. Therefore, inside each cell of the
 *  arrangement of all such lines, the number of visible voters is constant.
 *
 *  We construct all such lines, build all intersection points, and for each
 *  arrangement cell represented by a sample point (line intersection, line-mid
 *  segment sample, and a global outside sample), evaluate the number of visible
 *  voters directly. This is expensive in theory, but acceptable for the intended
 *  constraints of this classic problem.
 *
 *  Visibility test:
 *   voter visible from X iff segment X-voter does not properly intersect any
 *   obstacle edge and neither endpoint lies strictly inside an obstacle.
 *   Touching boundary is treated as blocked because obstacle exists "along the
 *   line segment". Thus any intersection with polygon boundary blocks, except
 *   when X or voter itself lies on that boundary; still blocked.
 *
 *  We avoid candidate X positions on obstacle boundaries or arrangement lines by
 *  sampling slightly off line segments / cells.
 */

public class Main {
    static final double EPS = 1e-9;
    static final double SAMPLE_SHIFT = 1e-6;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != '.' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 1;
                c = read();
                while (c > ' ' && c != -1) {
                    mul *= 0.1;
                    val += (c - '0') * mul;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) Math.round(nextDouble());
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
        Point add(Point o) { return new Point(x + o.x, y + o.y); }
        Point sub(Point o) { return new Point(x - o.x, y - o.y); }
        Point mul(double k) { return new Point(x * k, y * k); }
    }

    static class Segment {
        Point a, b;
        Segment(Point a, Point b) { this.a = a; this.b = b; }
    }

    static class Polygon {
        Point[] p;
        Segment[] edges;
        Polygon(Point[] p) {
            this.p = p;
            int n = p.length;
            edges = new Segment[n];
            for (int i = 0; i < n; i++) edges[i] = new Segment(p[i], p[(i + 1) % n]);
        }
    }

    static class Line {
        // ax + by + c = 0 normalized
        double a, b, c;
        Point p1, p2; // for direction
        Line(Point u, Point v) {
            p1 = u; p2 = v;
            double A = v.y - u.y;
            double B = u.x - v.x;
            double C = -(A * u.x + B * u.y);
            double norm = Math.hypot(A, B);
            A /= norm; B /= norm; C /= norm;
            if (A < -EPS || (Math.abs(A) <= EPS && B < -EPS)) {
                A = -A; B = -B; C = -C;
            }
            a = A; b = B; c = C;
        }
        double side(Point p) { return a * p.x + b * p.y + c; }
        Point dir() { return new Point(-b, a); }
    }

    static double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
    static double cross(Point a, Point b, Point c) { return cross(b.sub(a), c.sub(a)); }
    static double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }

    static int sgn(double x) {
        if (x > EPS) return 1;
        if (x < -EPS) return -1;
        return 0;
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return Math.abs(cross(a, b, p)) <= EPS &&
                Math.min(a.x, b.x) - EPS <= p.x && p.x <= Math.max(a.x, b.x) + EPS &&
                Math.min(a.y, b.y) - EPS <= p.y && p.y <= Math.max(a.y, b.y) + EPS;
    }

    static boolean segmentsIntersect(Segment s1, Segment s2) {
        Point a = s1.a, b = s1.b, c = s2.a, d = s2.b;
        double c1 = cross(a, b, c), c2 = cross(a, b, d);
        double c3 = cross(c, d, a), c4 = cross(c, d, b);
        int s1c = sgn(c1), s2c = sgn(c2), s3c = sgn(c3), s4c = sgn(c4);

        if (s1c == 0 && onSegment(a, b, c)) return true;
        if (s2c == 0 && onSegment(a, b, d)) return true;
        if (s3c == 0 && onSegment(c, d, a)) return true;
        if (s4c == 0 && onSegment(c, d, b)) return true;

        return s1c * s2c < 0 && s3c * s4c < 0;
    }

    static boolean pointOnPolygonBoundary(Point p, Polygon poly) {
        for (Segment e : poly.edges) if (onSegment(e.a, e.b, p)) return true;
        return false;
    }

    static boolean pointInPolygonStrict(Point p, Polygon poly) {
        if (pointOnPolygonBoundary(p, poly)) return false;
        boolean inside = false;
        int n = poly.p.length;
        for (int i = 0, j = n - 1; i < n; j = i++) {
            Point a = poly.p[j], b = poly.p[i];
            boolean cond = ((a.y > p.y) != (b.y > p.y));
            if (cond) {
                double xint = (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x;
                if (xint > p.x) inside = !inside;
            }
        }
        return inside;
    }

    static boolean blocked(Point x, Point voter, Polygon[] polys) {
        Segment sv = new Segment(x, voter);
        for (Polygon poly : polys) {
            if (pointOnPolygonBoundary(x, poly) || pointOnPolygonBoundary(voter, poly)) return true;
            if (pointInPolygonStrict(x, poly) || pointInPolygonStrict(voter, poly)) return true;
            for (Segment e : poly.edges) {
                if (segmentsIntersect(sv, e)) return true;
            }
        }
        return false;
    }

    static Point lineIntersection(Line l1, Line l2) {
        double det = l1.a * l2.b - l2.a * l1.b;
        if (Math.abs(det) <= EPS) return null;
        double x = (l2.c * l1.b - l1.c * l2.b) / det;
        double y = (l1.c * l2.a - l2.c * l1.a) / det;
        return new Point(x, y);
    }

    static String keyPoint(Point p) {
        long x = Math.round(p.x * 1e8);
        long y = Math.round(p.y * 1e8);
        return x + "#" + y;
    }

    static int evaluate(Point x, Point[] voters, Polygon[] polys) {
        for (Polygon poly : polys) {
            if (pointOnPolygonBoundary(x, poly) || pointInPolygonStrict(x, poly)) return -1;
        }
        int cnt = 0;
        for (Point v : voters) {
            if (!blocked(x, v, polys)) cnt++;
        }
        return cnt;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int M = fs.nextInt();

        Polygon[] polys = new Polygon[N];
        ArrayList<Point> vertices = new ArrayList<>();
        double minX = 1e100, minY = 1e100, maxX = -1e100, maxY = -1e100;

        for (int i = 0; i < N; i++) {
            int k = fs.nextInt();
            Point[] pts = new Point[k];
            for (int j = 0; j < k; j++) {
                double x = fs.nextDouble(), y = fs.nextDouble();
                pts[j] = new Point(x, y);
                vertices.add(pts[j]);
                minX = Math.min(minX, x);
                minY = Math.min(minY, y);
                maxX = Math.max(maxX, x);
                maxY = Math.max(maxY, y);
            }
            polys[i] = new Polygon(pts);
        }

        Point[] voters = new Point[M];
        for (int i = 0; i < M; i++) {
            double x = fs.nextDouble(), y = fs.nextDouble();
            voters[i] = new Point(x, y);
            minX = Math.min(minX, x);
            minY = Math.min(minY, y);
            maxX = Math.max(maxX, x);
            maxY = Math.max(maxY, y);
        }

        if (M == 0) {
            System.out.println(0);
            return;
        }

        ArrayList<Line> lines = new ArrayList<>();
        HashSet<String> lineSet = new HashSet<>();

        for (Point v : voters) {
            for (Point u : vertices) {
                if (Math.hypot(v.x - u.x, v.y - u.y) <= EPS) continue;
                Line ln = new Line(v, u);
                String key = Math.round(ln.a * 1e10) + "#" + Math.round(ln.b * 1e10) + "#" + Math.round(ln.c * 1e10);
                if (lineSet.add(key)) lines.add(ln);
            }
        }

        int best = 0;
        HashSet<String> tested = new HashSet<>();

        // A far outside sample point
        double span = Math.max(maxX - minX, maxY - minY) + 10.0;
        Point outside = new Point(maxX + 3 * span + 1, maxY + 5 * span + 2);
        int val = evaluate(outside, voters, polys);
        if (val > best) best = val;
        tested.add(keyPoint(outside));

        // Test all line intersections
        ArrayList<Point> intersections = new ArrayList<>();
        int L = lines.size();
        for (int i = 0; i < L; i++) {
            for (int j = i + 1; j < L; j++) {
                Point p = lineIntersection(lines.get(i), lines.get(j));
                if (p == null) continue;
                String kp = keyPoint(p);
                if (tested.add(kp)) {
                    intersections.add(p);
                    val = evaluate(p, voters, polys);
                    if (val > best) best = val;
                }
            }
        }

        // For each line, sample between consecutive intersection points on that line
        for (int i = 0; i < L; i++) {
            Line ln = lines.get(i);
            Point dir = ln.dir();
            ArrayList<Double> ts = new ArrayList<>();

            // project intersections on the line
            for (Point p : intersections) {
                if (Math.abs(ln.side(p)) <= 1e-7) {
                    double t = dot(p.sub(ln.p1), dir);
                    ts.add(t);
                }
            }

            // add far sentinels
            ts.add(-1e9);
            ts.add(1e9);
            Collections.sort(ts);

            for (int j = 0; j + 1 < ts.size(); j++) {
                double mid = (ts.get(j) + ts.get(j + 1)) / 2.0;
                Point base = ln.p1.add(dir.mul(mid));

                // move slightly off the line to get a cell sample on each side
                Point normal = new Point(ln.a, ln.b);
                double norm = Math.hypot(normal.x, normal.y);
                normal = new Point(normal.x / norm, normal.y / norm);

                Point s1 = base.add(normal.mul(SAMPLE_SHIFT));
                Point s2 = base.sub(normal.mul(SAMPLE_SHIFT));

                String k1 = keyPoint(s1);
                if (tested.add(k1)) {
                    val = evaluate(s1, voters, polys);
                    if (val > best) best = val;
                }

                String k2 = keyPoint(s2);
                if (tested.add(k2)) {
                    val = evaluate(s2, voters, polys);
                    if (val > best) best = val;
                }
            }
        }

        System.out.println(best);
    }
}

