import math

def point_on_segment(px, py, ax, ay, bx, by):
    # Check if point (px,py) lies on segment AB
    cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax)
    if abs(cross) > 1e-9:
        return False
    dot = (px - ax) * (bx - ax) + (py - ay) * (by - ay)
    if dot < 0:
        return False
    sqlen = (bx - ax) * (bx - ax) + (by - ay) * (by - ay)
    if dot > sqlen:
        return False
    return True

def segments_intersect(ax, ay, bx, by, cx, cy, dx, dy):
    # Check if AB and CD intersect (including endpoints)
    def orient(px, py, qx, qy, rx, ry):
        return (qx - px) * (ry - py) - (qy - py) * (rx - px)
    o1 = orient(ax, ay, bx, by, cx, cy)
    o2 = orient(ax, ay, bx, by, dx, dy)
    o3 = orient(cx, cy, dx, dy, ax, ay)
    o4 = orient(cx, cy, dx, dy, bx, by)

    if o1 == 0 and point_on_segment(cx, cy, ax, ay, bx, by): return True
    if o2 == 0 and point_on_segment(dx, dy, ax, ay, bx, by): return True
    if o3 == 0 and point_on_segment(ax, ay, cx, cy, dx, dy): return True
    if o4 == 0 and point_on_segment(bx, by, cx, cy, dx, dy): return True

    return (o1 > 0) != (o2 > 0) and (o3 > 0) != (o4 > 0)

def point_inside_polygon(px, py, poly):
    # Ray casting check
    inside = False
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i+1)%n]
        if ((y1 > py) != (y2 > py)):
            xinters = (x2 - x1) * (py - y1) / (y2 - y1) + x1
            if px < xinters:
                inside = not inside
    return inside

def visible(cx, cy, vx, vy, polygons):
    # Check if segment from candidate to voter is blocked
    for poly in polygons:
        n = len(poly)
        for i in range(n):
            x1, y1 = poly[i]
            x2, y2 = poly[(i+1)%n]
            if segments_intersect(cx, cy, vx, vy, x1, y1, x2, y2):
                # Check if the intersection is just the voter or candidate point
                if (abs(vx - x1) < 1e-9 and abs(vy - y1) < 1e-9) or \
                   (abs(vx - x2) < 1e-9 and abs(vy - y2) < 1e-9) or \
                   (abs(cx - x1) < 1e-9 and abs(cy - y1) < 1e-9) or \
                   (abs(cx - x2) < 1e-9 and abs(cy - y2) < 1e-9):
                    continue
                return False
        # Also check if candidate is inside polygon
        if point_inside_polygon(cx, cy, poly):
            return False
    return True

