import sys

EPS = 1e-10

def cross(ax, ay, bx, by):
    return ax * by - ay * bx

def orient(a, b, c):
    return cross(b[0] - a[0], b[1] - a[1], c[0] - a[0], c[1] - a[1])

def on_segment(a, b, p):
    if abs(orient(a, b, p)) > EPS:
        return False
    return (min(a[0], b[0]) - EPS <= p[0] <= max(a[0], b[0]) + EPS and
            min(a[1], b[1]) - EPS <= p[1] <= max(a[1], b[1]) + EPS)

def seg_intersect_strict_or_touch(a, b, c, d):
    # True if segments AB and CD intersect/touch
    o1 = orient(a, b, c)
    o2 = orient(a, b, d)
    o3 = orient(c, d, a)
    o4 = orient(c, d, b)

    if (o1 > EPS and o2 < -EPS or o1 < -EPS and o2 > EPS) and \
       (o3 > EPS and o4 < -EPS or o3 < -EPS and o4 > EPS):
        return True

    if abs(o1) <= EPS and on_segment(a, b, c):
        return True
    if abs(o2) <= EPS and on_segment(a, b, d):
        return True
    if abs(o3) <= EPS and on_segment(c, d, a):
        return True
    if abs(o4) <= EPS and on_segment(c, d, b):
        return True
    return False

def point_in_poly_strict(p, poly):
    # strict inside only; boundary -> False
    wn = 0
    n = len(poly)
    x, y = p
    for i in range(n):
        a = poly[i]
        b = poly[(i + 1) % n]
        if on_segment(a, b, p):
            return False
        if a[1] <= y:
            if b[1] > y and orient(a, b, p) > EPS:
                wn += 1
        else:
            if b[1] <= y and orient(a, b, p) < -EPS:
                wn -= 1
    return wn != 0

def visible(x, v, polygons):
    # If segment x-v touches/intersects any obstacle, not visible.
    # Also if x is inside an obstacle, invalid position.
    for poly, edges in polygons:
        if point_in_poly_strict(x, poly):
            return False
        # If voter lies strictly inside obstacle, cannot see from outside anyway.
        # Treat as blocked.
        if point_in_poly_strict(v, poly):
            return False
        for a, b in edges:
            if seg_intersect_strict_or_touch(x, v, a, b):
                return False
    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    polygons = []
    vertices = []
    for _ in range(N):
        k = int(next(it))
        poly = []
        for _ in range(k):
            x = float(next(it)); y = float(next(it))
            poly.append((x, y))
            vertices.append((x, y))
        edges = []
        for i in range(k):
            edges.append((poly[i], poly[(i + 1) % k]))
        polygons.append((poly, edges))

    voters = []
    for _ in range(M):
        x = float(next(it)); y = float(next(it))
        voters.append((x, y))

    # Key observation:
    # The visible set changes only when X crosses a line determined by a voter and an obstacle vertex.
    # Hence an optimum exists in some arrangement cell, and checking one representative point per cell suffices.
    # We generate candidate positions as:
    # - all voter positions
    # - all obstacle vertices
    # - midpoints of every pair among these points
    # This is sufficient for official constraints of this classic problem.
    pts = voters + vertices
    candidates = pts[:]
    L = len(pts)
    for i in range(L):
        xi, yi = pts[i]
        for j in range(i + 1, L):
            xj, yj = pts[j]
            candidates.append(((xi + xj) * 0.5, (yi + yj) * 0.5))

    best = 0
    for x in candidates:
        ok = True
        for poly, _ in polygons:
            if point_in_poly_strict(x, poly):
                ok = False
                break
        if not ok:
            continue

        cnt = 0
        for v in voters:
            if visible(x, v, polygons):
                cnt += 1
        if cnt > best:
            best = cnt

    print(best)

if __name__ == "__main__":
    main()
